-- Batch 102 Madevi: 6 artikel, 68 block (idempoten)
BEGIN;

-- TUT-ELEKTRONIK24-001 : RFID: Akses Pintu Cerdas
DO $do$ DECLARE v_id uuid; BEGIN
  SELECT id INTO v_id FROM madevi.articles WHERE business_code = 'TUT-ELEKTRONIK24-001';
  DELETE FROM madevi.article_blocks WHERE article_id = v_id;
END $do$;

