INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('c55ee52c-caa8-49eb-a523-f8294e641c29', 'TUT-ELEKTRONIK24-001', 'b4444444-4444-4444-4444-444444444444', 'RFID: Akses Pintu Cerdas', 'rfid-akses-pintu-cerdas', 'Buat sistem kunci pintu RFID dengan Arduino: dari komponen hingga kartu terdaftar.', 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Kunci Manual Tidak Praktis dan Tidak Aman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kunci pintu biasa mudah diduplikasi, sering hilang, dan tidak ada catatan siapa yang masuk. Untuk kos, kantor kecil, atau gudang, sistem akses kartu RFID memberi solusi murah: kartu ditempel ke pembaca, pintu terbuka otomatis, dan setiap kartu bisa dicabut aksesnya kapan saja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja RFID$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$RFID (Radio Frequency Identification) bekerja lewat gelombang radio jarak dekat. Kartu atau tag berisi chip pasif tanpa baterai; saat didekatkan ke pembaca RC522, chip mendapat daya dari medan radio lalu mengirimkan UID uniknya. Arduino membaca UID, mencocokkan dengan daftar yang diizinkan, lalu menggerakkan relay atau solenoid untuk membuka kunci.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan Alat dan Bahan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Arduino Uno atau Nano$$, $$Modul RFID RC522 + kartu dan tag bawaan$$, $$Relay 5V 1 channel atau modul solenoid lock 12V$$, $$Kabel jumper male-female dan breadboard$$, $$Library MFRC522 (instal via Library Manager)$$, $$Adaptor 5V/12V sesuai kebutuhan kunci$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Pembuatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Pasang library MFRC522 di Arduino IDE, lalu buka contoh DumpInfo untuk membaca UID kartumu.$$, $$Rangkai RC522 ke Arduino: SDA ke D10, SCK ke D13, MOSI ke D11, MISO ke D12, RST ke D9, 3V3 ke 3V3 (jangan 5V).$$, $$Catat UID kartu yang muncul di Serial Monitor, masukkan ke array daftar UID yang diizinkan di kode.$$, $$Hubungkan relay ke pin D7; output relay mengendalikan solenoid lock atau simulasi LED dulu untuk latihan.$$, $$Upload program: jika UID cocok, relay aktif 3 detik lalu mati; jika tidak cocok, bunyikan buzzer peringatan.$$, $$Uji dengan kartu terdaftar dan kartu asing; pastikan pintu hanya terbuka untuk kartu terdaftar.$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Hal yang Perlu Diwaspadai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kartu RFID standar (Mifare Classic) UID-nya bisa disalin dengan alat murah, jadi jangan andalkan untuk keamanan tinggi seperti brankas. Pisahkan catu daya solenoid dari Arduino agar tidak reset saat kunci aktif. Jangan gunakan sistem ini untuk pintu utama tanpa kunci mekanis cadangan; listrik padam berarti pintu tidak bisa dibuka dari luar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Setelah sistem berjalan stabil selama seminggu, tambahkan fitur: log waktu akses ke kartu SD, tombol exit dari dalam, dan mode tambah kartu baru tanpa mengubah kode. Untuk keamanan lebih tinggi, pelajari kartu Mifare DESFire atau tambahkan PIN keypad sebagai autentikasi ganda.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('cb923038-d7e8-4923-9f9f-609497229ccf', 'TUT-MASAK29-001', 'b7777777-7777-7777-7777-777777777777', 'Ayam Betutu: Resep Bali', 'ayam-betutu-resep-bali', 'Masak ayam betutu khas Bali yang empuk dan bumbunya meresap hingga ke tulang.', 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ayam Betutu Keras dan Bumbu Tidak Meresap$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Ayam betutu yang gagal biasanya alot, bumbunya hanya menempel di luar, dan aroma rempahnya kurang keluar. Penyebabnya hampir selalu sama: waktu marinasi terlalu singkat, api terlalu besar, dan bumbu base gede khas Bali tidak diulek sampai benar-benar halus.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Rahasia Betutu Bali$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Betutu adalah teknik memasak lambat khas Bali: ayam utuh dilumuri bumbu base gede (bawang merah, bawang putih, cabai, kemiri, kunyit, jahe, kencur, lengkuas, serai, terasi, dan daun jeruk), dibungkus daun pisang, lalu dipanggang atau dikukus berjam-jam hingga daging empuk dan bumbu meresap ke tulang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan Bahan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$1 ekor ayam kampung (±1 kg), bersihkan dan kerat-kerat$$, $$Bumbu halus: 10 bawang merah, 6 bawang putih, 8 cabai merah, 4 kemiri sangrai$$, $$Rempah: 3 cm kunyit, 3 cm jahe, 2 cm kencur, 4 cm lengkuas, 3 serai, 1 sdt terasi bakar$$, $$5 lembar daun jeruk, garam, gula merah, dan minyak kelapa secukupnya$$, $$Daun pisang untuk membungkus dan tali rafia$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Memasak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Ulek atau blender semua bumbu hingga sangat halus, lalu tumis dengan minyak kelapa sampai harum dan matang.$$, $$Lumuri ayam dengan bumbu di seluruh permukaan dan rongga perut; diamkan minimal 2 jam, idealnya semalaman di kulkas.$$, $$Bungkus ayam rapat dengan daun pisang berlapis dua, ikat dengan tali rafia.$$, $$Kukus 2 jam dengan api sedang, atau panggang dalam oven 160 derajat Celsius selama 2,5 jam.$$, $$Buka bungkusan, olesi sisa bumbu, lalu panggang lagi 15 menit agar permukaan sedikit kering dan harum.$$, $$Sajikan dengan nasi hangat, plecing kangkung, dan sambal matah.$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan memakai ayam broiler tua yang terlalu besar karena dagingnya mudah hancur sebelum bumbu meresap; ayam kampung muda paling pas. Bumbu yang kurang matang saat ditumis akan terasa langu. Daun pisang yang sobek membuat uap keluar dan ayam kering; lapisi dua lapis untuk aman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Penyelesaian: Cek Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Betutu berhasil jika daging mudah lepas dari tulang dengan garpu, bumbu meresap hingga ke dalam, dan aroma rempah terasa tanpa bau langu. Sisa betutu bisa disimpan di kulkas 3 hari; hangatkan dengan dikukus agar tidak kering.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e3ca744c-279c-4db7-b74d-10ea7c2554af', 'EXP-KIMIA41-001', 'c4444444-4444-4444-4444-444444444444', 'Nikel: Logam Baterai', 'nikel-logam-baterai', 'Mengenal nikel: dari tambang Indonesia hingga jantung baterai kendaraan listrik.', 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Nikel: Logam di Balik Baterai Modern$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Nikel adalah logam berwarna putih keperakan dengan simbol Ni dan nomor atom 28. Ia tahan karat, mudah dibentuk, dan menjadi bahan kunci baja nirkarat serta katoda baterai lithium-ion yang menggerakkan mobil listrik dan ponselmu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Penting Nikel$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Nikel bersifat feromagnetik seperti besi, meleleh pada sekitar 1455 derajat Celsius, dan tahan terhadap korosi karena membentuk lapisan oksida pelindung. Dalam tabel periodik ia berada di golongan 10, satu keluarga dengan paladium dan platina.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Indonesia: Raksasa Nikel Dunia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Indonesia memiliki cadangan nikel laterit terbesar di dunia, terutama di Sulawesi, Maluku, dan Papua. Sejak larangan ekspor bijih mentah, Indonesia membangun smelter dan kawasan industri untuk mengolah nikel menjadi feronikel, nikel matte, hingga prekursor baterai di dalam negeri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Nikel dalam Baterai Kendaraan Listrik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Katoda baterai NMC (nikel-mangan-kobalt) memakai nikel untuk menaikkan kepadatan energi sehingga mobil bisa menempuh jarak lebih jauh. Semakin tinggi kadar nikel, semakin besar kapasitasnya, tetapi juga semakin menantang dari sisi stabilitas dan keselamatan termal.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Dampak Lingkungan dan Tantangannya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Penambangan nikel laterit bersifat tambang terbuka yang mengubah bentang alam dan menghasilkan limbah. Pengolahan pirometalurgi boros energi, sementara hidrometalurgi menghasilkan limbah asam. Karena itu reklamasi tambang, daur ulang baterai bekas, dan teknologi pengolahan bersih menjadi kunci keberlanjutan industri nikel.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('13f8a92e-0f4a-44b5-a168-d3785b758aa2', 'EXP-SEJARAH30-001', 'c8888888-8888-8888-8888-888888888888', 'Pemberontakan Westerling', 'pemberontakan-westerling', 'Peristiwa APRA 1950: latar belakang, jalannya peristiwa, dan akhirnya.', 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Pemberontakan Westerling: Ujian Pertama NKRI$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Pada Januari 1950, lima bulan setelah pengakuan kedaulatan, Indonesia menghadapi pemberontakan bersenjata pertama: Angkatan Perang Ratu Adil (APRA) pimpinan Raymond Westerling menyerang Bandung dan Jakarta dengan tujuan menggagalkan pembubaran Negara Pasundan dan menggulingkan pemerintahan Republik Indonesia Serikat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang: Siapa Westerling$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Raymond Westerling adalah mantan kapten KNIL yang terkenal dengan aksi brutalnya di Sulawesi Selatan pada 1946-1947. Setelah pengakuan kedaulatan, ia menolak kembali ke Belanda dan membentuk APRA yang beranggotakan bekas KNIL, dengan ideologi Ratu Adil yang menjanjikan keadilan bagi para prajurit.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jalannya Peristiwa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pada 23 Januari 1950 pasukan APRA menyerang Bandung dan sempat menguasai beberapa titik, menewaskan puluhan anggota TNI. Mereka merencanakan serangan ke Jakarta untuk menangkap para pemimpin RIS pada 25 Januari, tetapi rencana bocor dan pasukan TNI sudah bersiaga sehingga serangan gagal total.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Akhir Pemberontakan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Setelah gagal di Jakarta, Westerling melarikan diri dengan bantuan pihak tertentu dan akhirnya kabur ke Singapura lalu ke Belanda. Para anak buahnya ditangkap dan diadili. Peristiwa ini mempercepat pembubaran negara-negara bagian dan kembalinya Indonesia ke bentuk negara kesatuan pada Agustus 1950.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Makna bagi Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Pemberontakan Westerling menjadi pelajaran bahwa kedaulatan yang baru diakui harus dipertahankan dengan ketegasan. Peristiwa ini juga menunjukkan soliditas TNI yang baru seumur jagung dalam menghadapi ancaman bersenjata, serta mempercepat terwujudnya NKRI yang utuh.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('1eb9e78e-35f9-40cf-8345-fda312b85e1a', 'SCH-SMA-EKO6-001', 'd5555555-5555-5555-5555-555555555555', 'Ekonomi Kelas 12: Pembangunan Ekonomi', 'ekonomi-kelas-12-pembangunan-ekonomi', 'Materi pembangunan ekonomi: pengertian, indikator, faktor, dan hambatan.', 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari bab ini, kamu diharapkan mampu menjelaskan pengertian pembangunan ekonomi, menyebutkan indikator keberhasilannya, mengidentifikasi faktor pendorong dan penghambat, serta menganalisis strategi pembangunan ekonomi Indonesia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Pembangunan Ekonomi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pembangunan ekonomi adalah upaya meningkatkan kesejahteraan masyarakat melalui pertumbuhan ekonomi yang disertai perubahan struktur ekonomi, pemerataan, dan peningkatan kualitas hidup. Berbeda dengan pertumbuhan ekonomi yang hanya mengukur kenaikan PDB, pembangunan ekonomi menekankan pemerataan dan keberlanjutan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Indikator Keberhasilan Pembangunan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Pendapatan per kapita yang meningkat dan merata$$, $$Indeks Pembangunan Manusia (IPM): kesehatan, pendidikan, standar hidup layak$$, $$Tingkat pengangguran dan kemiskinan yang menurun$$, $$Ketimpangan pendapatan rendah (rasio Gini kecil)$$, $$Kualitas lingkungan hidup yang terjaga$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Faktor Pendorong dan Penghambat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pendorong pembangunan antara lain sumber daya alam, sumber daya manusia berkualitas, modal dan teknologi, serta stabilitas politik. Penghambatnya meliputi keterbatasan modal, rendahnya kualitas SDM, ketergantungan pada komoditas mentah, birokrasi yang lambat, dan ketimpangan antarwilayah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$Jelaskan perbedaan pertumbuhan ekonomi dan pembangunan ekonomi!$$, $$Sebutkan tiga indikator keberhasilan pembangunan ekonomi beserta penjelasannya!$$, $$Analisislah dua hambatan utama pembangunan ekonomi Indonesia dan cara mengatasinya!$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Pertumbuhan ekonomi hanya mengukur kenaikan output/PDB, sedangkan pembangunan ekonomi mencakup perubahan struktur, pemerataan, dan kualitas hidup.$$, $$Pendapatan per kapita, IPM (kesehatan-pendidikan-standar hidup), dan penurunan kemiskinan/pengangguran.$$, $$Contoh: keterbatasan SDM berkualitas (diatasi dengan pendidikan vokasi) dan ketergantungan komoditas mentah (diatasi dengan hilirisasi industri).$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('ba98eb5b-e98e-4e12-bfda-7ddaa650a3f5', 'SCH-SD-IPS28-001', 'd1000001-0000-0000-0000-000000000001', 'IPS Kelas 1: Aturan di Rumah dan Sekolah', 'ips-kelas-1-aturan-di-rumah-dan-sekolah', 'Mengenal aturan di rumah dan sekolah serta mengapa kita harus menaatinya.', 'id', 5, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar bab ini, kamu dapat menyebutkan contoh aturan di rumah dan di sekolah, menjelaskan mengapa aturan itu ada, dan menunjukkan sikap menaati aturan dalam kehidupan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Aturan?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Aturan adalah ketentuan yang harus dipatuhi agar kehidupan berjalan tertib dan aman. Di mana pun kita berada, selalu ada aturan: di rumah, di sekolah, di jalan, bahkan saat bermain bersama teman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Contoh Aturan di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Merapikan tempat tidur setelah bangun pagi$$, $$Mencuci tangan sebelum makan$$, $$Meminta izin sebelum pergi bermain$$, $$Belajar pada waktu yang sudah disepakati$$, $$Berbicara sopan kepada orang tua$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Aturan di Sekolah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Datang tepat waktu sebelum bel berbunyi$$, $$Memakai seragam sesuai jadwal$$, $$Mengangkat tangan sebelum bertanya$$, $$Tidak berlari di koridor kelas$$, $$Membuang sampah pada tempatnya$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$Sebutkan tiga aturan yang ada di rumahmu!$$, $$Mengapa kita tidak boleh berlari di koridor sekolah?$$, $$Apa yang terjadi jika tidak ada aturan di kelas?$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Contoh: merapikan mainan, cuci tangan sebelum makan, tidur tepat waktu.$$, $$Karena bisa menabrak teman dan menyebabkan kecelakaan.$$, $$Kelas menjadi gaduh, tidak tertib, dan belajar tidak nyaman.$$])));
